22	const projectAt = args.indexOf('--project'), stateFile = projectAt < 0 ? null : path.resolve(args[projectAt + 1], '.writer/state.json');
23	function snap(name) { if (!stateFile || !fs.existsSync(stateFile)) return null; const bytes = fs.readFileSync(stateFile); fs.writeFileSync(path.join(dir, name), bytes, { flag: 'wx' }); return sha(bytes); }
24	const before = snap('before-state.json'), build_before = buildObservation(), start = Date.now();
25	if (exe === 'npm.cmd' && args.some(x => !/^[A-Za-z0-9:=_-]+$/.test(x))) throw Error('Unsafe npm arguments');
